contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will deposit some amount into c on behalf of this contract, then call withdrawAll and check effects.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        // Deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Read observable state before calling withdrawAll
        uint beforeContractBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;

        // Call withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterContractBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;

        // If the call did not revert, then the contract's balance must have decreased by exactly the caller's prior credit (which equals depositAmount),
        // and the caller's balance must have increased by that same amount.
        // We express prior credit via the deposit we just made: since credit is not public, we use the observable balances.
        // General rule: If not reverted, beforeContractBalance - afterContractBalance == afterCallerBalance - beforeCallerBalance

        assert(reverted || (beforeContractBalance - afterContractBalance == afterCallerBalance - beforeCallerBalance));
    }

    // Allow contract to receive Ether when c sends funds back
    receive() external payable {}
}

